    // =========================
    // DECODE / VALIDATE FILE
    // =========================
    const fileBuffer = decodeBase64File(file_base64);

    if (!fileBuffer || !fileBuffer.length) {
      return buildJsonResponse(400, { error: 'Decoded file is empty.' });
    }

    if (fileBuffer.length > MAX_FILE_SIZE_BYTES) {
      return buildJsonResponse(400, {
        error: 'File is too large. Maximum size is 5 MB.'
      });
    }

    // =========================
    // BUILD STORAGE PATH
    // =========================
    const safeFileName = sanitizeFileName(file_name);
    const extension = getFileExtension(safeFileName, file_type);
    const timestamp = Date.now();
    const storagePath = `${product_id}/product-${timestamp}.${extension}`;
    newlyUploadedPath = storagePath;

    // =========================
    // UPLOAD TO STORAGE
    // =========================
    const { error: uploadError } = await supabase.storage
      .from(PRODUCT_IMAGES_BUCKET)
      .upload(storagePath, fileBuffer, {
        contentType: file_type,
        upsert: false,
        cacheControl: '3600'
      });

    if (uploadError) {
      throw uploadError;
    }

    // =========================
    // GET PUBLIC URL
    // =========================
    const { data: publicUrlData } = supabase.storage
      .from(PRODUCT_IMAGES_BUCKET)
      .getPublicUrl(storagePath);

    const publicUrl = publicUrlData?.publicUrl;

    if (!publicUrl) {
      throw new Error('Failed to generate public image URL.');
    }

    // =========================
    // UPDATE PRODUCT ROW
    // =========================
    const { data: updatedProduct, error: updateError } = await supabase
      .from('products')
      .update({
        image_url: publicUrl,
        image_path: storagePath,
        updated_at: new Date().toISOString()
      })
      .eq('id', product_id)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    // =========================
    // DELETE OLD IMAGE (BEST EFFORT)
    // =========================
    // Only remove after DB update succeeds, and only if the old path exists
    // and is different from the new one.
    if (
      existingProduct.image_path &&
      existingProduct.image_path !== storagePath
    ) {
      try {
        await supabase.storage
          .from(PRODUCT_IMAGES_BUCKET)
          .remove([existingProduct.image_path]);
      } catch (cleanupError) {
        console.error('upload-product-image cleanup warning:', cleanupError);
      }
    }

    return buildJsonResponse(200, {
      success: true,
      message: 'Product image uploaded successfully.',
      image_url: publicUrl,
      image_path: storagePath,
      product: updatedProduct
    });
  } catch (error) {
    console.error('upload-product-image error:', error);

    // =========================
    // BEST-EFFORT ROLLBACK
    // =========================
    // If upload succeeded but DB update failed, remove the newly uploaded file.
    if (newlyUploadedPath) {
      try {
        await supabase.storage
          .from(PRODUCT_IMAGES_BUCKET)
          .remove([newlyUploadedPath]);
      } catch (rollbackError) {
        console.error('upload-product-image rollback warning:', rollbackError);
      }
    }

    return buildJsonResponse(500, {
      error: error.message || 'Server error'
    });
  }
};

// /.netlify/functions/upload-story-cover.js
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

const STORY_COVERS_BUCKET = 'story-covers';
const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif'
]);
const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;

// =========================
// HELPERS
// =========================
function jsonResponse(statusCode, payload) {
  return {
    statusCode,
    body: JSON.stringify(payload)
  };
}

function sanitizeFileName(fileName) {
  return String(fileName || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9.\-_]/g, '-')
    .replace(/-+/g, '-');
}

function getFileExtension(fileName, fileType) {
  const safeName = String(fileName || '').toLowerCase();

  if (safeName.includes('.')) {
    const ext = safeName.split('.').pop().replace(/[^a-z0-9]/g, '');
    if (ext) return ext;
  }

  switch (fileType) {
    case 'image/jpeg':
      return 'jpg';
    case 'image/png':
      return 'png';
    case 'image/webp':
      return 'webp';
    case 'image/gif':
      return 'gif';
    default:
      return 'bin';
  }
}

function decodeBase64File(fileBase64) {
  try {
    return Buffer.from(fileBase64, 'base64');
  } catch {
    throw new Error('Invalid base64 file data.');
  }
}

// =========================
// MAIN HANDLER
// =========================
export async function handler(event) {
  if (event.httpMethod !== 'POST') {
    return jsonResponse(405, { error: 'Method not allowed' });
  }

  const authHeader = event.headers.authorization || event.headers.Authorization;
  const token = authHeader?.replace(/^Bearer\s+/i, '');

  if (!token) {
    return jsonResponse(401, { error: 'Missing auth token' });
  }

  let newlyUploadedPath = null;

  try {
    // =========================
    // AUTH / ADMIN CHECK
    // =========================
    const {
      data: { user },
      error: userError
    } = await supabase.auth.getUser(token);

    if (userError || !user) {
      return jsonResponse(401, { error: 'Invalid user token' });
    }

    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    if (profileError) throw profileError;

    if (!profile || profile.role !== 'admin') {
      return jsonResponse(403, { error: 'Admin access required' });
    }

    // =========================
    // BODY PARSE
    // =========================
    let body = {};
    try {
      body = JSON.parse(event.body || '{}');
    } catch {
      return jsonResponse(400, { error: 'Invalid JSON body' });
    }

    const story_id = String(body.story_id || '').trim();
    const file_name = String(body.file_name || '').trim();
    const file_type = String(body.file_type || '').trim();
    const file_base64 = String(body.file_base64 || '').trim();

    if (!story_id || !file_name || !file_type || !file_base64) {
      return jsonResponse(400, {
        error: 'Missing required fields: story_id, file_name, file_type, file_base64'
      });
    }

    if (!ALLOWED_MIME_TYPES.has(file_type)) {
      return jsonResponse(400, {
        error: 'Unsupported file type. Allowed types: JPEG, PNG, WEBP, GIF.'
      });
    }

    // =========================
    // VERIFY STORY EXISTS
    // =========================
    const { data: story, error: storyError } = await supabase
      .from('stories')
      .select('id, cover_image_url, cover_image_path')
      .eq('id', story_id)
      .single();

    if (storyError || !story) {
      return jsonResponse(404, { error: 'Story not found' });
    }

    // =========================
    // DECODE / VALIDATE FILE
    // =========================
    const fileBuffer = decodeBase64File(file_base64);

    if (!fileBuffer || !fileBuffer.length) {
      return jsonResponse(400, { error: 'Decoded file is empty.' });
    }

    if (fileBuffer.length > MAX_FILE_SIZE_BYTES) {
      return jsonResponse(400, {
        error: 'File is too large. Maximum size is 5 MB.'
      });
    }

    // =========================
    // BUILD STORAGE PATH
    // =========================
    const safeFileName = sanitizeFileName(file_name);
    const extension = getFileExtension(safeFileName, file_type);
    const timestamp = Date.now();
    const storagePath = `${story_id}/cover-${timestamp}.${extension}`;
    newlyUploadedPath = storagePath;

    // =========================
    // UPLOAD TO STORAGE
    // =========================
    const { error: uploadError } = await supabase.storage
      .from(STORY_COVERS_BUCKET)
      .upload(storagePath, fileBuffer, {
        contentType: file_type,
        upsert: false,
        cacheControl: '3600'
      });

    if (uploadError) throw uploadError;

    // =========================
    // GET PUBLIC URL
    // =========================
    const { data: publicUrlData } = supabase.storage
      .from(STORY_COVERS_BUCKET)
      .getPublicUrl(storagePath);

    const publicUrl = publicUrlData?.publicUrl || null;

    if (!publicUrl) {
      throw new Error('Failed to generate public image URL.');
    }

    // =========================
    // UPDATE STORY ROW
    // =========================
    const { data: updatedStory, error: updateError } = await supabase
      .from('stories')
      .update({
        cover_image_url: publicUrl,
        cover_image_path: storagePath
      })
      .eq('id', story_id)
      .select()
      .single();

    if (updateError) throw updateError;

    // =========================
    // DELETE OLD COVER (BEST EFFORT)
    // =========================
    if (
      story.cover_image_path &&
      story.cover_image_path !== storagePath
    ) {
      try {
        await supabase.storage
          .from(STORY_COVERS_BUCKET)
          .remove([story.cover_image_path]);
      } catch (cleanupError) {
        console.error('upload-story-cover cleanup warning:', cleanupError);
      }
    }

    return jsonResponse(200, {
      success: true,
      cover_image_url: publicUrl,
      cover_image_path: storagePath,
      story: updatedStory
    });
  } catch (err) {
    console.error('upload-story-cover error:', err);

    // =========================
    // BEST-EFFORT ROLLBACK
    // =========================
    if (newlyUploadedPath) {
      try {
        await supabase.storage
          .from(STORY_COVERS_BUCKET)
          .remove([newlyUploadedPath]);
      } catch (rollbackError) {
        console.error('upload-story-cover rollback warning:', rollbackError);
      }
    }

    return jsonResponse(500, {
      error: err.message || 'Server error'
    });
  }
}

// /.netlify/functions/upload-story-page.js
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

const STORY_PAGES_BUCKET = 'story-pages';
const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;

function jsonResponse(statusCode, payload) {
  return {
    statusCode,
    body: JSON.stringify(payload)
  };
}

function decodeBase64File(fileBase64) {
  try {
    return Buffer.from(fileBase64, 'base64');
  } catch {
    throw new Error('Invalid base64 file data.');
  }
}

export async function handler(event) {
  if (event.httpMethod !== 'POST') {
    return jsonResponse(405, { error: 'Method not allowed' });
  }

  const authHeader = event.headers.authorization || event.headers.Authorization;
  const token = authHeader?.replace(/^Bearer\s+/i, '');

  if (!token) {
    return jsonResponse(401, { error: 'Missing auth token' });
  }

  let newlyUploadedPath = null;

  try {
    // =========================
    // AUTH
    // =========================
    const {
      data: { user },
      error: userError
    } = await supabase.auth.getUser(token);

    if (userError || !user) {
      return jsonResponse(401, { error: 'Invalid user token' });
    }

    const { data: profile } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    if (!profile || profile.role !== 'admin') {
      return jsonResponse(403, { error: 'Admin access required' });
    }

    // =========================
    // BODY
    // =========================
    const body = JSON.parse(event.body || '{}');
    const {
      story_id,
      file_name,
      file_type,
      file_base64,
      caption = null
    } = body;

    if (!story_id || !file_name || !file_type || !file_base64) {
      return jsonResponse(400, {
        error: 'Missing required fields'
      });
    }

    // =========================
    // VERIFY STORY
    // =========================
    const { data: story } = await supabase
      .from('stories')
      .select('id')
      .eq('id', story_id)
      .single();

    if (!story) {
      return jsonResponse(404, { error: 'Story not found' });
    }

    // =========================
    // NEXT PAGE NUMBER
    // =========================
    const { data: lastPageRow } = await supabase
      .from('story_pages')
      .select('page_number')
      .eq('story_id', story_id)
      .order('page_number', { ascending: false })
      .limit(1)
      .maybeSingle();

    const nextPageNumber = lastPageRow
      ? Number(lastPageRow.page_number) + 1
      : 1;

    // =========================
    // FILE
    // =========================
    const buffer = decodeBase64File(file_base64);

    if (!buffer || !buffer.length) {
      return jsonResponse(400, { error: 'Decoded file is empty.' });
    }

    if (buffer.length > MAX_FILE_SIZE_BYTES) {
      return jsonResponse(400, { error: 'File too large (max 5MB).' });
    }

    const extension = file_name.includes('.')
      ? file_name.split('.').pop().toLowerCase()
      : 'png';

    const safeExtension = extension.replace(/[^a-z0-9]/g, '') || 'png';

    const storagePath = `${story_id}/page-${nextPageNumber}-${Date.now()}.${safeExtension}`;
    newlyUploadedPath = storagePath;

    // =========================
    // UPLOAD
    // =========================
    const { error: uploadError } = await supabase.storage
      .from(STORY_PAGES_BUCKET)
      .upload(storagePath, buffer, {
        contentType: file_type,
        upsert: false
      });

    if (uploadError) throw uploadError;

    // =========================
    // PUBLIC URL
    // =========================
    const { data: publicUrlData } = supabase.storage
      .from(STORY_PAGES_BUCKET)
      .getPublicUrl(storagePath);

    const publicUrl = publicUrlData?.publicUrl || null;

    // =========================
    // INSERT ROW
    // =========================
    const { data: pageRow, error: insertError } = await supabase
      .from('story_pages')
      .insert([
        {
          story_id,
          page_number: nextPageNumber,
          image_url: publicUrl,
          image_path: storagePath, // ✅ NEW
          caption: caption?.trim() || null
        }
      ])
      .select()
      .single();

    if (insertError) throw insertError;

    return jsonResponse(200, {
      success: true,
      page: pageRow
    });
  } catch (err) {
    console.error('upload-story-page error:', err);

    // rollback
    if (newlyUploadedPath) {
      try {
        await supabase.storage
          .from(STORY_PAGES_BUCKET)
          .remove([newlyUploadedPath]);
      } catch (e) {
        console.error('rollback failed:', e);
      }
    }

    return jsonResponse(500, {
      error: err.message || 'Server error'
    });
  }
}

